<?php
require __DIR__.'/../cms/config.php'; require_login(); $u=current_user(); $role=$u['role']??'student';
$students=read_json('students');$results=read_json('results');$attendance=read_json('attendance');$invoices=read_json('invoices');$payments=read_json('payments');$messages=read_json('messages');$news=read_json('news');
$myStudent=null;
foreach($students as $s){if((int)($s['user_id']??0)===(int)($u['id']??0)||strcasecmp(($s['name']??''),($u['name']??''))===0){$myStudent=$s;break;}}
$sid=(int)($myStudent['id']??0);
$myResults=$sid?array_values(array_filter($results,fn($r)=>(int)($r['student_id']??0)===$sid)):[];$myAttend=$sid?array_values(array_filter($attendance,fn($r)=>(int)($r['student_id']??0)===$sid)):[];
$unread=count(array_filter($messages,fn($m)=>(int)($m['to_user_id']??0)===(int)$u['id']&&empty($m['read'])));
$inv=$sid?array_sum(array_map(fn($x)=>(int)$x['student_id']===$sid?(float)$x['amount']:0,$invoices)):0;$paid=$sid?array_sum(array_map(fn($x)=>(int)$x['student_id']===$sid?(float)$x['amount']:0,$payments)):0;
$present=count(array_filter($myAttend,fn($x)=>($x['status']??'')==='Present'));$attPct=count($myAttend)?round($present/count($myAttend)*100):0;
$avg=count($myResults)?round(array_sum(array_map(fn($r)=>((float)$r['mark']/(max(1,(float)$r['out_of']??100))*100),$myResults))/count($myResults)):0;
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h(ucfirst($role))?> Dashboard — Ridgefield</title><link rel="stylesheet" href="phase11.css"><link rel="stylesheet" href="../assets/phase53-complete.css"><style>.real-portal-logo img{display:block;width:auto;height:52px;max-width:220px;object-fit:contain}</style>
</head><body class="rf-dynamic"><div class="app"><aside class="side"><div class="real-portal-logo"><img src="../assets/2026.png" alt="Ridgefield Academy"></div><div class="brand">R I D G E F I E L D<small><?=h(strtoupper($role))?> PORTAL</small></div><nav><a class="active" href="dashboard.php">Dashboard</a><a href="messages.php">Messages<?php if($unread):?> (<?=$unread?>)<?php endif;?></a><?php if($role==='student'||$role==='parent'):?><a href="../cms/statement.php?student_id=<?=$sid?>">Fees</a><?php endif;?><a href="logout.php">Sign out</a></nav></aside><main><div class="top"><div><p class="muted">Ridgefield Academy</p><h1>Welcome, <?=h($u['name']??$u['username'])?></h1></div><a class="btn gold" href="messages.php">Open messages</a></div><?php if($unread):?><div class="notice"><strong><?=$unread?> unread message(s).</strong> Please check your inbox.</div><?php endif;?><div class="cards"><div class="card"><div class="metric"><?=h((string)count($myResults))?></div><div class="muted">Results recorded</div></div><div class="card"><div class="metric"><?=$avg?>%</div><div class="muted">Average mark</div></div><div class="card"><div class="metric"><?=$attPct?>%</div><div class="muted">Attendance</div></div><div class="card"><div class="metric">R <?=number_format($inv-$paid,2)?></div><div class="muted">Fee balance</div></div></div><div class="grid2"><section class="card"><h2>Academic progress</h2><?php if($myResults): foreach(array_slice(array_reverse($myResults),0,6) as $r):$pct=round(((float)$r['mark']/max(1,(float)$r['out_of']??100))*100);?><div class="event"><strong><?=h($r['assessment']??'Assessment')?></strong><span class="muted"> · <?=h($r['term']??'')?></span><p><?=h((string)$r['mark'])?> / <?=h((string)$r['out_of'])?> (<?=$pct?>%)</p><div class="bar"><span style="width:<?=$pct?>%"></span></div></div><?php endforeach;else:?><p class="muted">No results are available yet.</p><?php endif;?></section><section class="card"><h2>Latest announcements</h2><?php foreach(array_slice(array_reverse($news),0,5) as $n):?><div class="event"><strong><?=h($n['title']??'Announcement')?></strong><p class="muted"><?=h($n['date']??'')?></p></div><?php endforeach;if(!$news):?><p class="muted">No announcements.</p><?php endif;?></section></div></main></div><script src="assets/dynamic-site.js"></script>
</body></html>